import type { Predicate } from "@/clinical/schema/predicate"
import type { VignetteResult } from "@/clinical/vignettes/vignette"
import type { Bundle, Question, Questionnaire } from "@/clinical/schema/bundle"

/*
 * The review doc a PT reads and signs for each content version: every
 * question, branch, rule, track, and exercise in plain language, plus the
 * vignette results. Generated by publish-content; pure, so it's testable.
 */

/** A rule in words, such as "`pain-intensity` is at least 7". */
function describePredicate(predicate: Predicate): string {
  switch (predicate.op) {
    case "all":
      return predicate.of.length === 1
        ? describePredicate(predicate.of[0] as Predicate)
        : `all of (${predicate.of.map(describePredicate).join("; ")})`
    case "any":
      return predicate.of.length === 1
        ? describePredicate(predicate.of[0] as Predicate)
        : `any of (${predicate.of.map(describePredicate).join("; ")})`
    case "not":
      return `not (${describePredicate(predicate.of)})`
    case "eq":
      return typeof predicate.value === "boolean"
        ? `\`${predicate.question}\` is ${predicate.value ? "yes" : "no"}`
        : `\`${predicate.question}\` is ${String(predicate.value)}`
    case "in":
      return `\`${predicate.question}\` is one of ${predicate.values.join(", ")}`
    case "includes":
      return `\`${predicate.question}\` includes any of ${predicate.anyOf.join(", ")}`
    case "gte":
      return `\`${predicate.question}\` is at least ${predicate.value}`
    case "lte":
      return `\`${predicate.question}\` is at most ${predicate.value}`
  }
}

function describeAnswers(question: Question, regionIds: Array<string>): string {
  switch (question.type) {
    case "single":
      return `One of: ${question.options.map(option => `${option.label} (\`${option.id}\`)`).join(", ")}`
    case "multi":
      return `Any of: ${question.options.map(option => `${option.label} (\`${option.id}\`)`).join(", ")}`
    case "yes-no":
      return "Yes or no"
    case "scale":
      return `${question.min} (${question.minLabel}) to ${question.max} (${question.maxLabel})`
    case "body-map":
      return `Body regions: ${regionIds.map(id => `\`${id}\``).join(", ")}`
  }
}

function questionnaireSection(questionnaire: Questionnaire, regionIds: Array<string>): Array<string> {
  const lines = [`Starts at \`${questionnaire.start}\`.`, ""]
  for (const question of questionnaire.questions) {
    lines.push(`#### \`${question.id}\``, "", `> ${question.prompt}`, "")
    if (question.help !== undefined) {
      lines.push(`Help: ${question.help}`, "")
    }
    lines.push(`- Answers: ${describeAnswers(question, regionIds)}`)
    for (const edge of question.next) {
      const target = edge.goto === "complete"
        ? "finish"
        : `\`${edge.goto}\``
      lines.push(edge.when === undefined
        ? `- ${question.next.length > 1
          ? "Otherwise"
          : "Then"} → ${target}`
        : `- If ${describePredicate(edge.when)} → ${target}`)
    }
    lines.push("")
  }
  return lines
}

function safetyTable(rules: Bundle["safetyRules"]): Array<string> {
  return [
    "| Rule | Severity | Stops early | When | Why |",
    "|---|---|---|---|---|",
    ...rules.map(rule => `| \`${rule.id}\` | ${rule.severity} | ${rule.earlyStop ? "yes" : "no"} | ${describePredicate(rule.when)} | ${rule.summary} |`),
  ]
}

type ReviewDocInput = {
  bundle: Bundle
  checksum: string
  vignettes: Array<VignetteResult>
  /** ISO date the doc was generated. Passed in to keep this function pure. */
  generatedAt: string
}

function reviewDoc({ bundle, checksum, vignettes, generatedAt }: ReviewDocInput): string {
  const regionIds = bundle.regions.map(region => region.id)
  const isDraft = bundle.version.includes("-draft")
  const passed = vignettes.filter(result => result.passed).length
  const exercises = new Map(bundle.exercises.map(exercise => [exercise.id, exercise]))

  const lines: Array<string> = [
    `# ${bundle.title} content ${bundle.version}: clinical review`,
    "",
    `- Content: \`${bundle.id}\``,
    `- Version: \`${bundle.version}\`${isDraft ? " (draft)" : ""}`,
    `- Checksum (SHA-256): \`${checksum}\``,
    `- Generated: ${generatedAt}`,
    `- Vignettes: ${passed} of ${vignettes.length} passed`,
    "",
  ]
  if (isDraft) {
    lines.push("> **DRAFT. Not clinically approved.** This version may contain placeholder content.", "")
  }
  lines.push(
    "## Sign-off",
    "",
    "I have reviewed every question, rule, track, exercise, and vignette in this document and approve this content version, identified by the checksum above, for use.",
    "",
    "- Name and credentials: ______________________",
    "- Signature: ______________________",
    "- Date: ______________________",
    "",
    "Record the approval with `npm run content:approve`.",
    "",
    "## Body regions",
    "",
    ...bundle.regions.map(region => `- \`${region.id}\`: ${region.label}`),
    "",
    "## Assessment",
    "",
    ...questionnaireSection(bundle.assessment, regionIds),
    "### Safety rules",
    "",
    "Urgent: seek care now, with a call-911 screen. Refer: see a clinician before starting; the program stays locked. A rule that stops early ends the assessment as soon as it holds.",
    "",
    ...safetyTable(bundle.safetyRules),
    "",
    "### Track selection",
    "",
    "For eligible users only (no safety rule held). The first rule that holds picks the track and starting phase.",
    "",
    ...bundle.trackRules.map((rule, index) => rule.when === undefined
      ? `${index + 1}. Otherwise → \`${rule.track}\`, phase \`${rule.phase}\``
      : `${index + 1}. If ${describePredicate(rule.when)} → \`${rule.track}\`, phase \`${rule.phase}\``),
    "",
    "## Tracks",
    "",
  )

  for (const track of bundle.tracks) {
    lines.push(`### ${track.title} (\`${track.id}\`)`, "", track.summary, "")
    track.phases.forEach((phase, index) => {
      lines.push(`#### Phase ${index + 1}: ${phase.title} (\`${phase.id}\`)`, "", phase.summary, "")
      for (const session of phase.sessions) {
        lines.push(`- **${session.title}** (\`${session.id}\`)`)
        for (const dose of session.doses) {
          const parts = [
            `${dose.sets} set${dose.sets === 1
              ? ""
              : "s"}`,
            ...(dose.reps === undefined
              ? []
              : [`${dose.reps} reps`]),
            ...(dose.holdSeconds === undefined
              ? []
              : [`${dose.holdSeconds} s hold`]),
          ]
          lines.push(`  - ${exercises.get(dose.exercise)?.name ?? dose.exercise}: ${parts.join(", ")}`)
        }
      }
      lines.push("")
    })
  }

  lines.push("## Exercises", "")
  for (const exercise of bundle.exercises) {
    lines.push(
      `### ${exercise.name} (\`${exercise.id}\`)`,
      "",
      `Video: ${exercise.videoId === null
        ? "not recorded yet"
        : `\`${exercise.videoId}\``}`,
      "",
      "Cues:",
      ...exercise.cues.map(cue => `- ${cue}`),
      "",
      "Stop rules:",
      ...exercise.stopRules.map(rule => `- ${rule}`),
      "",
    )
  }

  const { checkIn } = bundle
  lines.push(
    "## Weekly check-in",
    "",
    ...questionnaireSection(checkIn.questionnaire, regionIds),
    "### Red-flag re-screen",
    "",
    "Any rule that holds stops the program and refers the user.",
    "",
    ...safetyTable(checkIn.safetyRules),
    "",
    "### Adjustment rules",
    "",
    "The first rule that holds proposes a decision.",
    "",
    ...checkIn.rules.map((rule, index) => rule.when === undefined
      ? `${index + 1}. \`${rule.id}\`: otherwise → ${rule.decision}`
      : `${index + 1}. \`${rule.id}\`: if ${describePredicate(rule.when)} → ${rule.decision}`),
    "",
    `The user counts as worse when ${describePredicate(checkIn.worsening)}.`,
    "",
    "The engine then applies these safety rules, whatever the content says:",
    "",
    "1. Any red flag at the re-screen stops the program and refers the user.",
    "2. A user who is worse never progresses: progress becomes hold.",
    "3. A program can't move before its first phase or past its last: those become hold.",
    "",
    "## Vignettes",
    "",
    "| Vignette | Result | Scenario |",
    "|---|---|---|",
    ...vignettes.map(result => `| \`${result.id}\` | ${result.passed
      ? "pass"
      : `**fail**: ${result.failures.join("; ")}`} | ${result.description} |`),
    "",
  )

  return lines.join("\n")
}

export {
  describePredicate,
  reviewDoc,
  type ReviewDocInput,
}
